"""Bought vs Sold page embedded in the dashboard."""
HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Daily Bought vs Sold Review</title><style>
body{font:15px Segoe UI,Arial,sans-serif;margin:0;background:#f3f6fa;color:#172231}main{max-width:1500px;margin:auto;padding:22px}h1{margin:0 0 12px}h2{margin-top:0}.banner{background:#fff0bd;padding:12px;border-radius:7px}.panel{padding:18px;background:white;border:1px solid #d5dfeb;border-radius:9px;margin:16px 0}button,input,select,textarea{font:inherit;padding:9px;border:1px solid #b7c6d5;border-radius:6px}button{cursor:pointer;background:#e9f1fa}button.primary{background:#246bb0;color:white}button:disabled{opacity:.5;cursor:default}label{display:block;font-weight:600;margin:12px 0 5px}.filters,.stats,.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.stats>div{padding:10px;min-width:150px}.stats strong{font-size:27px;display:block}.muted{color:#52667c;font-size:13px}p{line-height:1.5}.scroll{max-height:630px;overflow:auto}table{width:100%;min-width:1450px;border-collapse:collapse}td,th{padding:11px;vertical-align:top;text-align:left;border-bottom:1px solid #d5dfeb}th{background:#e9f0f7;position:sticky;top:0}td:nth-child(2){min-width:280px}td:last-child{min-width:250px}a{color:#1764aa}.badge{background:#fff3cb;padding:4px;border-radius:5px;display:inline-block}.money{white-space:nowrap}dialog{max-width:680px;width:calc(100% - 50px);border:1px solid #bbcbdc;border-radius:10px;padding:22px;max-height:88vh;overflow:auto}dialog::backdrop{background:#0007}dialog input,dialog select,dialog textarea{width:100%;box-sizing:border-box}#message,#matchError{white-space:pre-wrap}.danger{color:#a12828}@media(max-width:650px){main{padding:12px}.panel{padding:12px}}

.app-header{background:#162534;color:white;border-bottom:3px solid #e4b320;padding:17px 25px;font-weight:700;font-size:19px;display:flex;justify-content:space-between}.app-header small{font-size:13px;font-weight:400}.app-shell{max-width:1680px;margin:auto;display:grid;grid-template-columns:220px minmax(0,1fr);gap:22px;padding:22px}.app-shell main{padding:0;min-width:0;width:100%;box-sizing:border-box}.sidebar{background:white;border:1px solid #d5dfeb;border-radius:8px;padding:14px;align-self:start}.sidebar p{padding:10px;margin:3px 0;color:#53657a}.sidebar .nav-parent{color:#172231;font-weight:700;background:#eef3f9}.sidebar a{display:block;background:#246bb0;color:white;padding:12px 9px;border-radius:5px;margin:5px 0 5px 12px;text-decoration:none;font-weight:600}.sidebar small{color:#66788c}.eyebrow{color:#64768a;font-size:13px;margin:0 0 8px}.queue-tabs{display:flex;gap:9px;flex-wrap:wrap;margin:18px 0}.queue-tabs button{background:white;min-width:135px;text-align:left}.queue-tabs button strong{display:block;font-size:24px;margin-top:4px}.queue-tabs button[aria-pressed=true]{border:2px solid #246bb0;background:#edf5ff}.steps{display:flex;gap:20px;flex-wrap:wrap;color:#36516b;margin:16px 0}.panel h2{font-size:18px}.banner{font-size:13px;margin:12px 0}details summary{cursor:pointer;color:#246bb0}.stats{font-size:13px}.stats strong{font-size:20px}@media(max-width:850px){.app-shell{display:block;padding:12px}.sidebar{margin-bottom:18px}.sidebar p,.sidebar small{display:none}.sidebar a{margin:0}.app-header{font-size:16px}.app-header small{font-size:11px}}

#purchaseTable{table-layout:fixed;width:1730px;min-width:0}
#purchaseTable th{z-index:2;padding-right:24px;word-break:normal;overflow-wrap:normal}
#purchaseTable td{min-width:0;overflow-wrap:anywhere;word-break:normal}
#purchaseTable .money .muted{white-space:normal}
#purchaseTable .review-resize-handle{position:absolute;top:0;right:0;width:12px;height:100%;padding:0;border:0;border-radius:0;background:transparent;cursor:col-resize;touch-action:none;z-index:3}
#purchaseTable .review-resize-handle::after{content:"";position:absolute;top:9px;bottom:9px;left:5px;width:2px;background:#a1b3c7}
#purchaseTable .review-resize-handle:hover::after,#purchaseTable .review-resize-handle:focus-visible::after{background:#1764aa}
#purchaseTable.review-column-resizing{cursor:col-resize;user-select:none}
</style></head><body><main><div style="display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap"><h1>Bought vs Sold Review</h1><a href="/bought-vs-sold-guide" target="_blank" rel="noopener" style="padding:9px 14px;border:1px solid #b7c6d5;border-radius:6px;background:white;font-weight:600;text-decoration:none">How this works</a></div><p>Make sure purchased materials make it onto a Field Wise ticket.</p><div class="steps"><span><b>1.</b> Upload seven days of tickets</span><span><b>2.</b> Review overdue items and exceptions</span><span><b>3.</b> Verify sold quantities</span></div><p class="banner"><b>BOUGHT VS SOLD.</b> Review uses PO invoice attachments in this application. New or changed attachments are checked when you open or refresh this review. Confirmations do not change customer billing.</p><details><summary>Starting date and daily review rules</summary><p id="workflow"></p></details><div class="queue-tabs" id="queues" aria-label="Review queues"></div>
<section class="panel"><h2>Upload the last seven days from Field Wise</h2><p>Upload the complete rolling seven-day export each day. Overlapping sales are not added twice. Changed tickets replace their prior version; the history is retained. Tickets no longer present in a complete loaded window are marked inactive. Earlier history outside that window stays available.</p>
<form id="upload"><div class="filters"><div><label for="file">Field Wise ticket lines</label><input type="file" id="file" accept=".xlsx,.xlsm" required></div><div><label for="through">Export covers through</label><input type="date" id="through" required></div><button type="submit" class="primary" id="uploadBtn">Import and compare</button></div></form><p id="message" role="status"></p><p class="muted">Sold statuses: Submitted, Approved, Invoiced. Other statuses are retained but do not qualify for confirmation. Confirm the export's through date; the window is that date and the preceding six days.</p></section>
<details class="panel"><summary>Data coverage and comparison details</summary><div class="stats" id="stats"></div><p id="coverage"></p><p class="muted">Cost and selling price are shown separately. Matching does not require equal prices because material may be marked up. Exact catalogue links are suggestions, not confirmations. Units and quantity must be verified. Candidate ticket quantities may appear against more than one purchase; they are not additive and cannot be confirmed twice.</p><div id="states"></div><p id="stale" class="danger"></p></details>
<section class="panel"><h2>Purchase-line review</h2><div class="filters"><input type="search" id="search" placeholder="PO, job, vendor, part or description" aria-label="Search lines"><select id="state" aria-label="Filter state"><option value="">All states</option></select><select id="issueGroupFilter" aria-label="Issue group filter"><option value="">All issue groups</option></select><select id="issueStatusFilter" aria-label="Issue status filter"><option value="">All issue statuses</option><option>Open</option><option>In progress</option><option>Waiting on information</option><option>Resolved</option></select><button type="button" id="exportCsv">Export this view</button><select id="timing" aria-label="Timing filter"><option value="">All purchase ages</option></select><button id="refresh" type="button">Refresh</button><button id="resetColumnWidths" type="button">Reset column widths</button></div><p class="muted">Drag a column header’s right edge to resize. Widths are remembered in this browser.</p><p id="count"></p><div class="actions"><button id="prev">Previous</button><span id="page"></span><button id="next">Next</button></div><div class="scroll"><table id="purchaseTable"><colgroup><col style="width:220px"><col style="width:400px"><col style="width:140px"><col style="width:170px"><col style="width:170px"><col style="width:250px"><col style="width:380px"></colgroup><thead><tr><th>PO / job / vendor</th><th>Purchased line</th><th>Bought quantity / unit</th><th>Purchase cost</th><th>Confirmed sold / remaining</th><th>Purchase timing / review state</th><th>Possible Field Wise sales</th></tr></thead><tbody id="rows"></tbody></table></div></section>
<section class="panel" id="orphanPanel" hidden><h2>Issues with changed or unavailable source lines</h2><p>These investigations keep their original purchase details. Closing one does not confirm the replacement line sold.</p><div id="orphanIssues"></div></section><section class="panel"><h2>Review history</h2><div id="events"></div></section><section class="panel"><h2>Recent daily uploads</h2><div id="imports"></div></section>
<dialog id="issueDialog"><form id="issueForm"><h2>Investigate purchase line</h2><p id="issueContext"></p><label for="issueGroup">Issue group</label><input id="issueGroup" maxlength="100" required placeholder="e.g. Missing on ticket, Wrong job, Parser review"><label for="issueDescription">What needs to be figured out?</label><textarea id="issueDescription" rows="3" maxlength="4000" required></textarea><label for="issueStatus">Status</label><select id="issueStatus"><option>Open</option><option>In progress</option><option>Waiting on information</option><option>Resolved</option></select><label for="issueNotes">Updates / resolution notes</label><textarea id="issueNotes" rows="3" maxlength="4000"></textarea><p>Resolving an issue does not mark any quantity sold.</p><p id="issueError" role="alert"></p><button class="primary" type="submit">Save issue</button> <button id="cancelIssue" type="button">Cancel</button></form></dialog><dialog id="match"><form id="matchForm"><h2>Confirm a material sale</h2><p id="buyContext"></p><label for="sale">Matching ticket line</label><select id="sale" required></select><p id="saleContext"></p><label for="qty">Purchased quantity covered by this ticket</label><input id="qty" type="number" step="any" min="0.000001" required><label for="factor">Purchased units covered by one ticket unit</label><input id="factor" type="number" step="any" min="0.000001" placeholder="Verify first, e.g. 1 for EA to EA" required><label for="unitNote">Verified units / conversion notes</label><textarea id="unitNote" rows="3" required placeholder="Example: 1 EA purchased = 1 EA sold. Confirmed against invoice and ticket."></textarea><p id="matchError" class="danger" role="alert"></p><div class="actions"><button class="primary" type="submit">Confirm quantity</button><button id="cancelMatch" type="button">Cancel</button></div></form></dialog>
</main><script>
function initPurchaseColumns(){
  const table=document.getElementById('purchaseTable');
  const headers=Array.from(table.querySelectorAll('thead th'));
  const columns=Array.from(table.querySelectorAll('colgroup col'));
  const defaults=[220,400,140,170,170,250,380], minimums=[160,180,120,140,140,180,220];
  const storageKey='pm:material-review:column-widths:v1';
  let widths=defaults.slice();
  try {
    const saved=JSON.parse(localStorage.getItem(storageKey)||'null');
    if(Array.isArray(saved)&&saved.length===defaults.length&&saved.every(v=>typeof v==='number'&&Number.isFinite(v))){
      widths=saved.map((v,i)=>Math.max(minimums[i],Math.min(1400,Math.round(v))));
    }
  }catch{}
  const handles=[];
  function apply(){
    columns.forEach((col,i)=>col.style.width=widths[i]+'px');
    table.style.width=widths.reduce((a,b)=>a+b,0)+'px';
    handles.forEach((handle,i)=>handle.setAttribute('aria-valuenow',widths[i]));
  }
  function save(){try{localStorage.setItem(storageKey,JSON.stringify(widths));}catch{}}
  headers.forEach((header,i)=>{
    const name=header.textContent.trim(),handle=document.createElement('button');
    handle.type='button';handle.className='review-resize-handle';
    handle.setAttribute('role','separator');handle.setAttribute('aria-orientation','vertical');
    handle.setAttribute('aria-label','Resize '+name+' column');
    handle.setAttribute('aria-valuemin',minimums[i]);handle.setAttribute('aria-valuemax','1400');
    handle.title='Drag to resize; arrow keys adjust width; Home restores this column';
    function change(value){widths[i]=Math.max(minimums[i],Math.min(1400,Math.round(value)));apply();}
    handle.addEventListener('pointerdown',event=>{
      if(event.button!==0)return;
      event.preventDefault();event.stopPropagation();
      const start=event.clientX,initial=widths[i],pointer=event.pointerId;
      table.classList.add('review-column-resizing');
      const move=e=>{if(e.pointerId===pointer){e.preventDefault();change(initial+e.clientX-start);}};
      const finish=()=>{
        table.classList.remove('review-column-resizing');save();
        window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',finish);
        window.removeEventListener('pointercancel',finish);window.removeEventListener('blur',finish);
      };
      window.addEventListener('pointermove',move);window.addEventListener('pointerup',finish);
      window.addEventListener('pointercancel',finish);window.addEventListener('blur',finish);
    });
    handle.addEventListener('keydown',event=>{
      if(!['ArrowLeft','ArrowRight','Home'].includes(event.key))return;
      event.preventDefault();event.stopPropagation();
      change(event.key==='Home'?defaults[i]:widths[i]+(event.key==='ArrowLeft'?-1:1)*(event.shiftKey?50:10));save();
    });
    handles.push(handle);header.appendChild(handle);
  });
  document.getElementById('resetColumnWidths').addEventListener('click',()=>{widths=defaults.slice();apply();save();});
  apply();
}
initPurchaseColumns();

let data=null,page=0,currentBuy=null,firstLoad=true,queue='all',editingIssue=null,issueDraft='';const size=100;const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const money=n=>Number(n||0).toLocaleString('en-US',{style:'currency',currency:'USD'});
async function api(url,opts={}){const r=await fetch(url,opts);const v=await r.json();if(!r.ok)throw Error(v.error||'Request failed');return v;}
function queueFor(b){if(b.issue&&b.issue.status!=='Resolved')return 'issues';if(b.timing_state==='Confirmed sold')return 'confirmed';if(b.timing_state.startsWith('Within 0'))return 'waiting';if(b.timing_state==='Over 3 days — review unconfirmed quantity')return 'overdue';return 'attention';}
function drawQueues(){document.getElementById('queues').innerHTML=[['all','All purchases'],['waiting','Waiting · 0–3 days'],['overdue','Overdue review'],['attention','Needs attention'],['issues','Open issues'],['confirmed','Confirmed sold']].map(([id,label])=>`<button type="button" data-queue="${id}" aria-pressed="${queue===id}">${label}<strong>${data.purchases.filter(b=>id==='all'||queueFor(b)===id).length}</strong></button>`).join('');document.querySelectorAll('[data-queue]').forEach(button=>button.onclick=()=>{queue=button.dataset.queue;page=0;document.getElementById('state').value='';document.getElementById('timing').value='';document.getElementById('issueGroupFilter').value='';document.getElementById('issueStatusFilter').value='';render();});}
function render(){if(!data)return;const q=document.getElementById('search').value.toLowerCase(),state=document.getElementById('state').value,timing=document.getElementById('timing').value;const all=data.purchases.filter(b=>(queue==='all'||queueFor(b)===queue)&&(!state||b.state===state)&&(!timing||b.timing_state===timing)&&(!document.getElementById('issueGroupFilter').value||b.issue?.issue_group===document.getElementById('issueGroupFilter').value)&&(!document.getElementById('issueStatusFilter').value||b.issue?.status===document.getElementById('issueStatusFilter').value)&&(!q||[b.po_number,b.job,b.vendor,b.description,b.part_code].join(' ').toLowerCase().includes(q)));page=Math.max(0,Math.min(page,Math.ceil(all.length/size)-1));const shown=all.slice(page*size,(page+1)*size);document.getElementById('count').textContent=all.length+' review rows; showing '+shown.length+(all.length?'':'. No purchases in this view. Older invoices are excluded from the daily workflow.');document.getElementById('page').textContent='Page '+(page+1)+' of '+Math.max(1,Math.ceil(all.length/size));document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=(page+1)*size>=all.length;
document.getElementById('rows').innerHTML=shown.map(b=>`<tr><td><b>${esc(b.po_number)}</b><div>Job ${esc(b.job)}</div><div>${esc(b.vendor)}</div><a href="/uploads/${encodeURIComponent(b.invoice_file)}" target="_blank" rel="noopener">Open invoice</a></td><td>${b.line_number?'Line '+b.line_number+' / ':''}${esc(b.part_code||'')}<div>${esc(b.description)}</div><div class="muted">Invoice ${esc(b.invoice_number||'unread')} / ${esc(b.invoice_date||'date unread')}</div></td><td>${b.bought_qty===null?'Not extracted':esc(b.bought_qty)} ${esc(b.unit||'(unit not established)')}</td><td class="money">${b.purchase_line_amount!==undefined?money(b.purchase_line_amount):'Not extracted'}<div class="muted">${b.purchase_unit_cost!==undefined?money(b.purchase_unit_cost)+' per purchased unit':''}</div></td><td>${b.bought_qty!==null?b.confirmed_qty+' confirmed / '+Math.max(0,b.bought_qty-b.confirmed_qty)+' not confirmed':'Needs parsing'}</td><td><b>${esc(b.timing_state)}</b><div class="muted">${b.age_days===null?'Age unknown':(b.age_days<0?'Purchase date needs review':b.age_days+' calendar days')} as of ${esc(b.timing_as_of||'no coverage')}</div><p><span class="badge">${esc(b.state)}</span></p>${data.can_edit&&b.base_state==='Candidate sale — verify units and quantity'&&b.confirmed_qty<b.bought_qty?`<p><button data-confirm="${esc(b.purchase_key)}">Review / confirm quantity</button></p>`:''}${b.issue?`<p><b>${esc(b.issue.issue_group)} · ${esc(b.issue.status)}</b><br>${esc(b.issue.description)}<br><span class="muted">${esc(b.issue.notes)}</span></p>`:''}${data.can_edit?`<p><button data-issue="${esc(b.purchase_key)}">${b.issue?'Update issue':'Flag issue'}</button></p>`:''}${(b.matches||[]).map(m=>`<p class="muted">Confirmed ${m.bought_qty} purchased units by ${esc(m.confirmed_by)}${data.can_edit?` <button data-unconfirm="${m.id}">Undo confirmation</button>`:''}</p>`).join('')}</td><td>${b.candidates.length?b.candidates.map(s=>`<p><b>Ticket ${esc(s.ticket_number)} / Job ${esc(s.order_number)}</b><br>${esc(s.item)}<br>Qty ${s.quantity} @ ${money(s.rate)} = ${money(s.amount)}<br>${esc(s.ticket_date)} / ${esc(s.status)}<br>${s.counts_as_sold?'Sold status':'Does not count as sold under selected statuses'}</p>`).join(''):'No exact catalogue candidate in loaded history.'}</td></tr>`).join('');drawQueues();document.querySelectorAll('[data-issue]').forEach(b=>b.onclick=()=>openIssue(b.dataset.issue));document.querySelectorAll('[data-unconfirm]').forEach(b=>b.onclick=async()=>{if(!confirm('Undo this quantity confirmation? The change will stay in review history.'))return;try{await api('/api/material-review/unconfirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:Number(b.dataset.unconfirm)})});await load();}catch(e){document.getElementById('message').textContent=e.message;}});document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>openMatch(b.dataset.confirm));}
async function load(){data=await api('/api/material-review');const selected=document.getElementById('state').value;document.getElementById('state').innerHTML='<option value="">All states</option>'+Object.keys(data.states).sort().map(s=>`<option value="${esc(s)}">${esc(s)} (${data.states[s]})</option>`).join('');document.getElementById('state').value=selected;document.getElementById('through').value=data.coverage.at(-1)||'';
const timingSelect=document.getElementById('timing'),priorTiming=timingSelect.value;timingSelect.innerHTML='<option value="">All purchase ages</option>'+Object.entries(data.timing_states).sort().map(([s,n])=>`<option value="${esc(s)}">${esc(s)} (${n})</option>`).join('');timingSelect.value=firstLoad?'':priorTiming;firstLoad=false;
const groupFilter=document.getElementById('issueGroupFilter'),priorGroup=groupFilter.value;groupFilter.innerHTML='<option value="">All issue groups</option>'+[...new Set(data.purchases.filter(b=>b.issue).map(b=>b.issue.issue_group))].sort().map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('');groupFilter.value=priorGroup;
document.getElementById('uploadBtn').disabled=!data.can_edit;
document.getElementById('events').innerHTML=(data.events||[]).slice(0,15).map(e=>`<p><b>${esc(e.action)}</b> · ${esc(e.created_at)} · ${esc(e.actor)}<details><summary>Details</summary><pre style="white-space:pre-wrap">${esc(JSON.stringify(JSON.parse(e.payload),null,2))}</pre></details></p>`).join('')||'<p>No review changes recorded yet.</p>';
document.getElementById('orphanPanel').hidden=!data.orphan_issues?.length;document.getElementById('orphanIssues').innerHTML=(data.orphan_issues||[]).map(i=>{const original=JSON.parse(i.source_json);return `<p><b>${esc(original.po_number)} · ${esc(i.issue_group)} · ${esc(i.status)}</b><br>${esc(original.description)}<br>${esc(i.description)}<br>${esc(i.notes)} ${data.can_edit?`<button data-orphan="${esc(i.purchase_key)}">Update retained issue</button>`:''}</p>`;}).join('');document.querySelectorAll('[data-orphan]').forEach(b=>b.onclick=()=>openIssue(b.dataset.orphan));
if(data.orphan_issues?.some(i=>i.status!=='Resolved'))document.getElementById('events').innerHTML+=`<p class="danger">${data.orphan_issues.length} saved issues have changed or unavailable source lines. Their history is retained; review them before closing.</p>`;

document.getElementById('workflow').textContent='Daily workflow starts '+data.start_date+'. Only purchases dated on or after this date are in the working queue. Earlier purchases are excluded; no historical cleanup is required. Undated invoices uploaded since the start are kept for date review. Unresolved quantities carry forward even when their purchase date leaves the next seven-day export. '+data.excluded_review_rows+' older or undated historical review rows excluded. Invoice data refreshed: '+data.purchase_snapshot+'.';
document.getElementById('stats').innerHTML=[['PO invoice records',data.source_invoice_count],['Purchase review rows',data.purchases.length],['Ticket lines retained (all types)',data.sales.length],['Confirmed quantity links',data.matches.length]].map(([s,n])=>`<div><strong>${n}</strong>${s}</div>`).join('');document.getElementById('coverage').textContent='Sales coverage loaded: '+(data.coverage[0]||'none')+' through '+(data.coverage.at(-1)||'none')+'. Timing is assessed through the latest loaded sales day, not today. Ages use calendar days from the invoice purchase date: 0–3 waiting; over 3 needs review. Every day since purchase must be covered before an overdue flag is shown. An unconfirmed quantity is not proof of a missed sale.';document.getElementById('states').textContent=Object.entries(data.states).map(([s,n])=>s+': '+n).join(' · ');document.getElementById('stale').textContent=data.stale_matches.length?data.stale_matches.length+' prior confirmations need rechecking because source ticket lines changed. They are excluded from confirmed quantities.':'';document.getElementById('imports').innerHTML=data.imports.map(i=>`<p>${esc(i.source_file)} — ${esc(i.window_start)} to ${esc(i.window_end)} / ${i.row_count} rows / ${esc(i.imported_at)} / ${esc(i.imported_by)}</p>`).join('');render();}
function issueFields(){return {issue_group:document.getElementById('issueGroup').value,description:document.getElementById('issueDescription').value,status:document.getElementById('issueStatus').value,notes:document.getElementById('issueNotes').value};}
function openIssue(key){editingIssue=data.purchases.find(b=>b.purchase_key===key);if(!editingIssue){const retained=data.orphan_issues.find(i=>i.purchase_key===key);editingIssue={...JSON.parse(retained.source_json),purchase_key:key,issue:retained};}const i=editingIssue.issue||{};document.getElementById('issueContext').textContent=editingIssue.po_number+' / '+editingIssue.description;document.getElementById('issueGroup').value=i.issue_group||'';document.getElementById('issueDescription').value=i.description||'';document.getElementById('issueStatus').value=i.status||'Open';document.getElementById('issueNotes').value=i.notes||'';document.getElementById('issueError').textContent='';issueDraft=JSON.stringify(issueFields());document.getElementById('issueDialog').showModal();}
function closeIssue(){if(JSON.stringify(issueFields())!==issueDraft&&!confirm('Discard unsaved issue changes?'))return;document.getElementById('issueDialog').close();editingIssue=null;}
document.getElementById('cancelIssue').onclick=closeIssue;document.getElementById('issueDialog').addEventListener('cancel',e=>{e.preventDefault();closeIssue();});
window.addEventListener('beforeunload',e=>{if(editingIssue&&JSON.stringify(issueFields())!==issueDraft){e.preventDefault();e.returnValue='';}});
document.getElementById('issueForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/api/material-review/issue',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({purchase_key:editingIssue.purchase_key,expected_revision:editingIssue.issue?.revision||0,...issueFields()})});document.getElementById('issueDialog').close();editingIssue=null;await load();}catch(error){document.getElementById('issueError').textContent=error.message;}finally{button.disabled=false;}};
document.getElementById('issueStatusFilter').onchange=()=>{page=0;render();};document.getElementById('issueGroupFilter').onchange=()=>{page=0;render();};
document.getElementById('exportCsv').onclick=()=>{const rows=[['PO','Job','Vendor','Invoice','Invoice date','Item','Bought quantity','Unit','Purchase cost','Confirmed quantity','Timing','Review state','Issue group','Issue status','Issue description']];const q=document.getElementById('search').value.toLowerCase(),s=document.getElementById('state').value,t=document.getElementById('timing').value,g=document.getElementById('issueGroupFilter').value,i=document.getElementById('issueStatusFilter').value;data.purchases.filter(b=>(queue==='all'||queueFor(b)===queue)&&(!s||b.state===s)&&(!t||b.timing_state===t)&&(!g||b.issue?.issue_group===g)&&(!i||b.issue?.status===i)&&(!q||[b.po_number,b.job,b.vendor,b.description,b.part_code].join(' ').toLowerCase().includes(q))).forEach(b=>rows.push([b.po_number,b.job,b.vendor,b.invoice_number,b.invoice_date,b.description,b.bought_qty,b.unit,b.purchase_line_amount,b.confirmed_qty,b.timing_state,b.state,b.issue?.issue_group,b.issue?.status,b.issue?.description]));const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'"+'$&').replaceAll('"','""')+'"';const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bought-vs-sold-review.csv';a.click();URL.revokeObjectURL(a.href);};
function openMatch(key){currentBuy=data.purchases.find(b=>b.purchase_key===key);document.getElementById('matchForm').reset();document.getElementById('buyContext').textContent=currentBuy.po_number+' / '+currentBuy.description+' / bought '+currentBuy.bought_qty+' '+(currentBuy.unit||'unit unconfirmed');document.getElementById('sale').innerHTML=currentBuy.candidates.filter(s=>s.counts_as_sold&&s.quantity>0).map(s=>`<option value="${esc(s.sales_line_id)}">Ticket ${esc(s.ticket_number)} — ${esc(s.item)} — qty ${s.quantity} — ${esc(s.status)}</option>`).join('');document.getElementById('qty').value=Math.max(0,currentBuy.bought_qty-currentBuy.confirmed_qty);document.getElementById('matchError').textContent='';document.getElementById('match').showModal();showSale();}
function showSale(){const s=currentBuy.candidates.find(s=>s.sales_line_id===document.getElementById('sale').value);document.getElementById('saleContext').textContent=s?`${s.description} / ${s.quantity} ticket units @ ${money(s.rate)}; confirm the unit basis before allocating.`:'No positive sale quantity available.';}
document.getElementById('sale').onchange=showSale;document.getElementById('cancelMatch').onclick=()=>document.getElementById('match').close();document.getElementById('matchForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/material-review/confirm',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({purchase_key:currentBuy.purchase_key,sales_line_id:document.getElementById('sale').value,bought_qty:document.getElementById('qty').value,bought_units_per_sale_unit:document.getElementById('factor').value,unit_note:document.getElementById('unitNote').value})});document.getElementById('match').close();await load();}catch(e){document.getElementById('matchError').textContent=e.message;}};
document.getElementById('upload').onsubmit=async e=>{e.preventDefault();const b=document.getElementById('uploadBtn');b.disabled=true;try{const f=new FormData();f.append('file',document.getElementById('file').files[0]);f.append('window_end',document.getElementById('through').value);const r=await api('/api/material-review/upload',{method:'POST',body:f});document.getElementById('message').textContent=r.duplicate_file?'Identical export already loaded; no sales counted twice.':`${r.row_count} source rows read; ${r.changed_tickets} tickets added/revised; ${r.removed_tickets} removed from the latest complete window. History preserved.`;await load();}catch(error){document.getElementById('message').textContent=error.message;}finally{b.disabled=false;}};
document.getElementById('search').oninput=()=>{page=0;render();};document.getElementById('timing').onchange=()=>{page=0;render();};document.getElementById('state').onchange=()=>{page=0;render();};document.getElementById('prev').onclick=()=>{page--;render();};document.getElementById('next').onclick=()=>{page++;render();};document.getElementById('refresh').onclick=()=>load().catch(e=>document.getElementById('message').textContent=e.message);load().catch(e=>document.getElementById('message').textContent=e.message);
</script></body></html>'''
